function getStoredTheme() {
  try {
    const storedTheme = localStorage.getItem(STORAGE_KEYS.theme);
    return storedTheme === "light" || storedTheme === "dark" ? storedTheme : "";
  } catch {
    return "";
  }
}

function getPreferredTheme() {
  const storedTheme = getStoredTheme();
  if (storedTheme) {
    return storedTheme;
  }

  if (window.matchMedia?.("(prefers-color-scheme: light)").matches) {
    return "light";
  }

  return "dark";
}

function applyTheme(theme, persist = false) {
  const nextTheme = theme === "light" ? "light" : "dark";
  document.documentElement.dataset.theme = nextTheme;
  document.body.dataset.theme = nextTheme;
  document.body.classList.toggle("theme-light", nextTheme === "light");
  document.body.classList.toggle("theme-dark", nextTheme === "dark");

  if (themeToggleLabel) {
    themeToggleLabel.textContent = nextTheme === "light" ? "Tema escuro" : "Tema claro";
  }

  if (themeToggle) {
    themeToggle.setAttribute("aria-pressed", String(nextTheme === "light"));
  }

  if (persist) {
    try {
      localStorage.setItem(STORAGE_KEYS.theme, nextTheme);
    } catch (error) {
      console.warn("[local-rush] Falha ao gravar tema:", error);
    }
  }
}

function toggleTheme() {
  const currentTheme = document.body.dataset.theme === "light" ? "light" : "dark";
  applyTheme(currentTheme === "light" ? "dark" : "light", true);

  if (searchMap) {
    scheduleMapResize();
  }
}

function loadLeaflet() {
  if (window.L && typeof window.L.map === "function") {
    return Promise.resolve();
  }

  if (leafletLoadPromise) {
    return leafletLoadPromise;
  }

  leafletLoadPromise = new Promise((resolve, reject) => {
    const existingScript = document.querySelector(`script[src="${LEAFLET_SCRIPT_SRC}"]`);
    if (existingScript) {
      existingScript.addEventListener("load", resolve, { once: true });
      existingScript.addEventListener("error", reject, { once: true });
      return;
    }

    const script = document.createElement("script");
    script.src = LEAFLET_SCRIPT_SRC;
    script.defer = true;
    script.onload = resolve;
    script.onerror = () => reject(new Error("Leaflet indisponivel."));
    document.head.appendChild(script);
  });

  return leafletLoadPromise;
}

