  backdrop-filter: blur(20px);
  display: flex;
  flex-direction: column;
  gap: 34px;
  z-index: 10;
}

body[data-theme="light"] .sidebar {
  background:
    linear-gradient(180deg, var(--sidebar), rgba(238, 249, 245, 0.94)),
    linear-gradient(90deg, rgba(0, 141, 130, 0.08), transparent 54%);
  box-shadow: 18px 0 54px rgba(38, 92, 85, 0.08);
}

.brand {
  color: var(--text);
  text-decoration: none;
  display: flex;
  align-items: center;
  gap: 14px;
  min-height: 62px;
}

.brand::after {
  content: "";
  position: absolute;
  left: 20px;
  right: 20px;
  top: 94px;
  height: 1px;
  background: linear-gradient(90deg, transparent, var(--border-strong), transparent);
  opacity: 0.75;
}

.brand-mark {
  width: 54px;
  height: 54px;
  flex: 0 0 auto;
  border-radius: 18px;
  display: grid;
  place-items: center;
  filter: drop-shadow(0 0 18px var(--brand-aura));
}

.brand-mark img {
  width: 100%;
  height: 100%;
  display: block;
}

.brand-copy {
  display: grid;
  gap: 2px;
}

.brand-copy strong {
  font-size: 1.24rem;
  letter-spacing: 0;
  color: var(--text);
}

.brand-copy small {
  color: var(--brand-route);
  font-size: 0.74rem;
  text-transform: uppercase;
  letter-spacing: 0.12em;
}

.brand-copy small::before {
  content: "";
  width: 7px;
  height: 7px;
  margin-right: 7px;
  border-radius: 999px;
  background: var(--brand-radar);
  box-shadow: 0 0 12px var(--brand-aura);
  display: inline-block;
  vertical-align: 1px;
}

.tabs {
  display: grid;
  gap: 12px;
}

.tab-button {
  width: 100%;
  border: 1px solid transparent;
  background: transparent;
  color: var(--muted);
  border-radius: 999px;
  min-height: 48px;
  padding: 0 12px;
  display: flex;
  gap: 12px;
  align-items: center;
  cursor: pointer;
  text-align: left;
  position: relative;
  transition: transform 0.12s ease, background-color 0.12s ease, border-color 0.12s ease, color 0.12s ease;
}

.tab-button img {
  width: 30px;
  height: 30px;
  padding: 7px;
  border-radius: 999px;
  background: rgba(140, 251, 241, 0.1);
  display: block;
}

.tab-button:hover {
  color: var(--text);
  transform: translateX(2px);
}

.tab-button.is-active {
  color: var(--text);
  border-color: var(--border-strong);
  background:
    radial-gradient(circle at 18% 50%, var(--brand-aura), transparent 34%),
    linear-gradient(90deg, var(--accent-soft), rgba(255, 255, 255, 0.04));
  box-shadow: inset 3px 0 0 var(--brand-radar), inset 0 0 0 1px rgba(255, 255, 255, 0.03), 0 12px 30px rgba(0, 0, 0, 0.2);
}

body[data-theme="light"] .tab-button.is-active {
  background:
    radial-gradient(circle at 18% 50%, rgba(0, 141, 130, 0.12), transparent 36%),
    linear-gradient(90deg, rgba(255, 255, 255, 0.94), rgba(232, 248, 244, 0.72));
  box-shadow: inset 3px 0 0 var(--brand-radar), 0 14px 34px rgba(26, 74, 68, 0.1);
}

.tab-button.is-active img {
  background: linear-gradient(180deg, var(--brand-radar), var(--brand-route));
  filter: none;
}

.sidebar-footer {
  margin-top: auto;
  display: grid;
  gap: 12px;
}

.sidebar-footer p {
  margin: 0;
  color: var(--muted);
  font-size: 0.78rem;
}

.theme-toggle {
  border: 1px solid var(--border);
  border-radius: 999px;
  min-height: 42px;
  padding: 0 13px;
  display: inline-flex;
  align-items: center;
  gap: 10px;
  color: var(--text);
  background: var(--surface-soft);
  cursor: pointer;
}

body[data-theme="light"] .theme-toggle {
  background: rgba(255, 255, 255, 0.88);
}

.theme-toggle-icon {
  width: 18px;
  height: 18px;
  border-radius: 999px;
  background: linear-gradient(90deg, var(--accent) 50%, transparent 50%);
  border: 1px solid var(--accent);
  box-shadow: 0 0 16px rgba(140, 251, 241, 0.28);
}

.app-shell {
  width: min(1480px, 100%);
  min-width: 0;
  margin: 0 auto;
  padding: 26px;
  display: grid;
  gap: 18px;
}

.topbar {
  min-height: 92px;
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 20px 22px;
  background:
    radial-gradient(circle at 92% 0%, rgba(184, 255, 104, 0.13), transparent 30%),
    linear-gradient(135deg, var(--surface), rgba(19, 50, 53, 0.66));
  box-shadow: var(--shadow);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
}

body[data-theme="light"] .topbar {
  background:
    radial-gradient(circle at 90% 0%, rgba(102, 181, 27, 0.12), transparent 30%),
    linear-gradient(135deg, rgba(255, 255, 255, 0.98), rgba(224, 246, 240, 0.86));
}

.eyebrow {
  margin: 0 0 5px;
  font-size: 0.7rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--accent);
  font-weight: 800;
}

.topbar h1,
.panel h2 {
  margin: 0;
  line-height: 1.1;
  letter-spacing: 0;
}

.topbar h1 {
  font-size: 1.78rem;
}

.view-subtitle {
  margin: 8px 0 0;
  max-width: 70ch;
  color: var(--muted);
  line-height: 1.45;
}

.hero-kpi {
  min-width: 420px;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
}

.hero-kpi span {
  min-height: 54px;
  border: 1px solid var(--border);
  border-radius: 18px;
  padding: 10px 12px;
  display: grid;
  gap: 2px;
  color: var(--muted);
  background: rgba(255, 255, 255, 0.035);
}

body[data-theme="light"] .hero-kpi span {
  background: rgba(255, 255, 255, 0.76);
}

.hero-kpi strong {
  color: var(--text);
  font-size: 0.92rem;
}

.hero-kpi small {
  color: var(--muted);
}

.views-stack {
  display: grid;
  gap: 18px;
}

.view-panel[hidden] {
  display: none !important;
}

.view-panel {
  animation: viewIn 0.08s ease-out both;
  will-change: opacity, transform;
}

@keyframes viewIn {
  from {
    opacity: 0;
    transform: translateY(2px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.dashboard-grid {
  display: grid;
  grid-template-columns: minmax(310px, 0.74fr) minmax(0, 1.26fr);
  gap: 18px;
  align-items: stretch;
}

.dashboard-secondary-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 330px;
  gap: 18px;
  margin-top: 18px;
  align-items: start;
}

.panel {
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  background:
    linear-gradient(155deg, rgba(184, 255, 104, 0.045), transparent 28%),
    linear-gradient(155deg, var(--surface), var(--surface-soft));
  box-shadow: var(--shadow);
  padding: 18px;
}

body[data-theme="light"] .panel {
  background:
    linear-gradient(155deg, rgba(102, 181, 27, 0.055), transparent 28%),
    linear-gradient(155deg, rgba(255, 255, 255, 0.98), rgba(236, 248, 244, 0.94));
}

.panel-heading,
.panel-header {
  margin-bottom: 14px;
}

.panel-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 16px;
}

.panel-header p {
  margin: 0;
  color: var(--muted);
}

.search-panel {
  min-height: 100%;
}

.search-form {
  display: grid;
  gap: 13px;
}

.form-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}

.location-query-field,
.form-hint,
.checkbox-field {
  grid-column: 1 / -1;
}

.form-hint {
  margin: -2px 0 0;
  color: var(--muted);
  font-size: 0.82rem;
  line-height: 1.45;
}

label {
  display: grid;
  gap: 7px;
  font-size: 0.82rem;
  color: var(--muted);
}

input,
select {
  width: 100%;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: rgba(0, 0, 0, 0.22);
  color: var(--text);
  min-height: 44px;
  padding: 0 12px;
  outline: none;
}

body[data-theme="light"] input,
body[data-theme="light"] select {
  background: rgba(255, 255, 255, 0.9);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.8);
}

input:focus,
select:focus,
button:focus-visible,
a:focus-visible {
  border-color: var(--accent-strong);
  box-shadow: 0 0 0 3px var(--accent-soft);
}

.advanced-field {
  color: var(--muted);
}

.checkbox-field {
  display: flex;
  align-items: center;
  gap: 8px;
  color: var(--text);
}

.checkbox-field input {
  min-height: auto;
  width: 17px;
  height: 17px;
  accent-color: var(--accent-strong);
}

.actions-row {
  display: grid;
  grid-template-columns: 1fr;
  gap: 9px;
}

.button {
  border: 1px solid var(--border);
  border-radius: 999px;
  min-height: 44px;
  padding: 0 15px;
  cursor: pointer;
  color: var(--text);
  transition: transform 0.2s ease, border-color 0.2s ease, background-color 0.2s ease;
}

.button:hover,
.mini-button:hover,
.table-action-button:hover {
  transform: translateY(-1px);
  border-color: var(--accent-strong);
}

.button.primary {
  border-color: rgba(140, 251, 241, 0.5);
  background:
    linear-gradient(90deg, rgba(255, 255, 255, 0.22), transparent 32%),
    linear-gradient(180deg, var(--brand-radar), var(--brand-route) 52%, var(--brand-pin));
  color: #031112;
  font-weight: 800;
  box-shadow: 0 16px 34px rgba(88, 244, 228, 0.18);
}

.button.secondary {
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.06), rgba(255, 255, 255, 0.025)),
    rgba(255, 255, 255, 0.04);
}

body[data-theme="light"] .button.secondary,
body[data-theme="light"] .mini-button,
body[data-theme="light"] .table-action-button {
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.92), rgba(239, 249, 245, 0.78)),
    rgba(255, 255, 255, 0.82);
}

.button[disabled] {
  opacity: 0.6;
  cursor: not-allowed;
}

.status-message,
.error-message {
  min-height: 1.1rem;
  margin: 0;
  font-size: 0.86rem;
}

.status-message {
  color: var(--warning);
}

.error-message {
  color: var(--danger);
}

.map-panel {
  min-height: 560px;
  padding: 18px;
}

.map-tools {
  display: grid;
  justify-items: end;
  gap: 9px;
  text-align: right;
}

.map-tools p {
  max-width: 320px;
  font-size: 0.84rem;
}

.map-shell {
  position: relative;
  width: 100%;
  min-height: 476px;
  height: calc(100% - 76px);
  border-radius: 26px;
  border: 1px solid var(--border-strong);
  overflow: hidden;
  background:
    linear-gradient(90deg, rgba(88, 244, 228, 0.08) 1px, transparent 1px),
    linear-gradient(rgba(88, 244, 228, 0.08) 1px, transparent 1px),
    radial-gradient(circle at 50% 45%, rgba(140, 251, 241, 0.14), transparent 40%),
    rgba(1, 7, 9, 0.94);
  background-size: 46px 46px, 46px 46px, auto, auto;
}

body[data-theme="light"] .map-shell {
  background:
    linear-gradient(90deg, rgba(0, 141, 130, 0.08) 1px, transparent 1px),
    linear-gradient(rgba(0, 141, 130, 0.08) 1px, transparent 1px),
    radial-gradient(circle at 50% 45%, rgba(0, 141, 130, 0.12), transparent 40%),
    #eef8f4;
}

#map,
.map-preview {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
}

#map {
  z-index: 1;
}

.map-preview {
  z-index: 2;
  display: none;
  border: 0;
  background: rgba(6, 11, 17, 0.94);
}

.map-shell.is-fallback #map {
  display: none;
}

.map-shell.is-fallback .map-preview {
  display: block;
}

.leaflet-container {
  font: inherit;
  background: #061013;
}

.map-popup {
  display: grid;
  gap: 6px;
  min-width: 190px;
}

.map-popup strong {
  font-size: 0.88rem;
  color: #0f1724;
}

.map-popup p {
  margin: 0;
  font-size: 0.78rem;
  line-height: 1.3;
  color: #2a3a52;
}

.map-popup a {
  font-size: 0.78rem;
  color: #0d766d;
  text-decoration: none;
}

.results-panel {
  padding: 18px;
}

.results-wrap {
  overflow: auto;
  max-width: 100%;
  border: 1px solid var(--border);
  border-radius: 22px;
  background: rgba(0, 0, 0, 0.13);
}

body[data-theme="light"] .results-wrap {
  background: rgba(255, 255, 255, 0.72);
}

table {
  width: 100%;
  border-collapse: collapse;
  min-width: 850px;
}

tbody tr {
  position: relative;
}

tr {
  transition: background-color 0.18s ease, box-shadow 0.18s ease;
}

tr[data-company-id] {
  cursor: pointer;
}

tr[data-company-id]:hover {
  background: var(--accent-soft);
}

tr.is-map-selected {
  background: var(--accent-soft);
  box-shadow: inset 4px 0 0 var(--accent);
}

th,
td {
  padding: 15px 14px;
  text-align: left;
  border-bottom: 1px solid rgba(255, 255, 255, 0.07);
  vertical-align: top;
}

body[data-theme="light"] th,
body[data-theme="light"] td {
  border-bottom-color: rgba(15, 70, 65, 0.08);
}

th {
  font-size: 0.72rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--muted);
}

td {
  font-size: 0.9rem;
}

.company-main {
  display: grid;
  gap: 5px;
}

.company-main strong {
  font-size: 0.98rem;
}

.company-address {
  color: var(--muted);
  font-size: 0.82rem;
  line-height: 1.35;
}

.category-chip {
  display: inline-flex;
  align-items: center;
  border: 1px solid var(--border);
  border-radius: 999px;
  min-height: 30px;
  padding: 0 10px;
  color: var(--text);
  background:
    linear-gradient(90deg, var(--accent-soft), transparent 72%),
    linear-gradient(180deg, rgba(255, 255, 255, 0.07), rgba(255, 255, 255, 0.025));
  white-space: nowrap;
}

body[data-theme="light"] .category-chip {
  background:
    linear-gradient(90deg, rgba(0, 141, 130, 0.1), transparent 72%),
    linear-gradient(180deg, rgba(255, 255, 255, 0.96), rgba(238, 248, 245, 0.86));
}

.category-chip::before {
  content: "";
  width: 7px;
  height: 7px;
  margin-right: 8px;
  border-radius: 999px;
  background: var(--brand-route);
  box-shadow: 0 0 12px var(--brand-aura);
}

.contact-group {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
}

.contact-group span,
.contact-group a,
.map-link,
.mini-link {
  color: var(--text);
  text-decoration: none;
}

.contact-group a,
.map-link,
.mini-link {
  border: 1px solid var(--border);
  border-radius: 999px;
  min-height: 28px;
  padding: 5px 9px;
  display: inline-flex;
  align-items: center;
  background: rgba(255, 255, 255, 0.045);
}

body[data-theme="light"] .contact-group a,
body[data-theme="light"] .map-link,
body[data-theme="light"] .mini-link {
  background: rgba(255, 255, 255, 0.9);
}

.contact-group a:hover,
.map-link:hover,
.mini-link:hover {
  border-color: var(--accent-strong);
}

.badge {
  display: inline-flex;
  align-items: center;
  border-radius: 999px;
  font-size: 0.76rem;
  padding: 6px 11px;
  border: 1px solid transparent;
  font-weight: 800;
}

.score-stack {
  display: grid;
  gap: 6px;
  justify-items: start;
}

.score-hint {
  color: var(--muted);
  font-size: 0.76rem;
  white-space: nowrap;
}

.badge-alta {
  color: #061312;
  background: linear-gradient(180deg, var(--brand-radar), #77df54);
  border-color: rgba(184, 255, 104, 0.6);
  box-shadow: 0 0 18px rgba(184, 255, 104, 0.16);
}

.badge-media {
  color: #241505;
  background: linear-gradient(180deg, #ffd48a, #efa84d);
  border-color: rgba(255, 186, 84, 0.48);
}

.badge-baixa {
  color: #fff1f3;
  background: linear-gradient(180deg, #e45c74, #a83249);
  border-color: rgba(255, 120, 120, 0.42);
}

.table-action-button,
.mini-button {
  border: 1px solid var(--border);
  border-radius: 999px;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.07), rgba(255, 255, 255, 0.025)),
    rgba(255, 255, 255, 0.05);
  color: var(--text);
  min-height: 32px;
  padding: 0 11px;
  cursor: pointer;
  transition: transform 0.2s ease, border-color 0.2s ease;
}

.table-action-button.is-saved {
  border-color: rgba(184, 255, 104, 0.5);
  color: var(--warning);
}

.empty-state {
  text-align: center;
  color: var(--muted);
  padding: 28px;
}

.activity-panel {
  display: grid;
  gap: 4px;
}

.activity-grid {
  display: block;
}

.activity-card {
  border: 1px solid var(--border);
  border-radius: 22px;
  padding: 14px;
  background: rgba(255, 255, 255, 0.04);
  display: none;
}

.activity-card.is-active {
  display: block;
  border-color: var(--border-strong);
}

.activity-card h3 {
  margin: 0 0 9px;
  font-size: 0.96rem;
}

.search-help-text {
  margin: 0 0 12px;
  color: var(--muted);
  font-size: 0.86rem;
}

.quick-location-grid {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.activity-card ul {
  margin: 0;
  padding-left: 0;
  list-style: none;
  color: var(--muted);
  display: grid;
  gap: 8px;
}

.activity-item {
  border: 1px solid var(--border);
  border-radius: 16px;
  padding: 10px 12px;
  background: rgba(255, 255, 255, 0.04);
  display: grid;
  gap: 9px;
}

body[data-theme="light"] .activity-item {
  background: rgba(255, 255, 255, 0.78);
}

.activity-item-main {
  display: grid;
  gap: 3px;
}

.activity-title {
  color: var(--text);
  font-size: 0.9rem;
}

.activity-meta {
  color: var(--muted);
  font-size: 0.78rem;
}

.activity-item-actions {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}

.list-view-panel {
  min-height: calc(100vh - 178px);
}

.list-panel {
  min-height: calc(100vh - 178px);
  display: grid;
  grid-template-rows: auto 1fr;
}

.standalone-list {
  margin: 0;
  padding: 0;
  list-style: none;
  display: grid;
  align-content: start;
  gap: 12px;
}

.standalone-list > li {
  color: var(--muted);
}

.standalone-list .activity-item {
  border-radius: 22px;
  padding: 14px 16px;
  background:
    linear-gradient(135deg, var(--brand-aura), transparent 34%),
    rgba(255, 255, 255, 0.04);
}

.standalone-list .activity-title {
  font-size: 0.96rem;
}

.standalone-list .activity-meta {
  font-size: 0.82rem;
}

.footer-note {
  margin: 2px 0 0;
  font-size: 0.84rem;
  color: var(--muted);
  text-align: center;
}

@media (max-width: 1180px) {
  .app-frame {
    grid-template-columns: 96px minmax(0, 1fr);
  }

  .sidebar {
    padding: 22px 14px;
    align-items: center;
  }

  .brand-copy,
  .tab-button span,
  .sidebar-footer p,
  #theme-toggle-label {
    display: none;
  }

  .tab-button {
    justify-content: center;
    padding: 0;
  }

  .theme-toggle {
    width: 48px;
    justify-content: center;
    padding: 0;
  }

  .dashboard-grid {
    grid-template-columns: 1fr;
  }

  .dashboard-secondary-grid {
    grid-template-columns: 1fr;
  }

  .map-panel {
    min-height: 520px;
  }
}

@media (orientation: portrait) and (min-width: 761px) {
  .app-frame {
    grid-template-columns: 232px minmax(0, 1fr);
  }

  .sidebar {
    padding: 24px 16px;
    align-items: stretch;
  }

  .brand-copy {
    display: grid;
  }

  .brand-copy strong {
    font-size: 1rem;
  }

  .brand-copy small {
    font-size: 0.66rem;
  }

  .tab-button span,
  #theme-toggle-label {
    display: inline;
  }

  .theme-toggle {
    width: auto;
    justify-content: flex-start;
    padding: 0 13px;
  }

  .sidebar-footer p {
    display: block;
  }

  .tab-button {
    min-height: 44px;
    gap: 10px;
    justify-content: flex-start;
    padding: 0 10px;
  }

  .tab-button img {
    width: 25px;
    height: 25px;
    padding: 5px;
  }

  .app-shell {
    padding: 18px;
  }

  .topbar {
    align-items: flex-start;
